using System;
using System.Buffers.Binary;
using System.Text;

public sealed record StatusReply(
    ushort RequestId, bool ValueValid, bool Alarm,
    short RawTemperatureTenths, decimal? TemperatureC, string Name);

public static class StatusV1Parser
{
    private static readonly UTF8Encoding StrictUtf8 = new(false, true);

    public static StatusReply Parse(ReadOnlySpan<byte> body)
    {
        // 前篇的 FrameReader 已交出完整 body；此處只驗證內部格式。
        if (body.Length < 8)
            throw new FormatException("status body is shorter than its fixed fields");
        if (body[0] != 1)
            throw new FormatException($"unsupported version {body[0]}");
        if (body[1] != 0x21)
            throw new FormatException($"unexpected message type {body[1]:X2}");

        ushort requestId = BinaryPrimitives.ReadUInt16BigEndian(body.Slice(2, 2));
        byte flags = body[4];
        if ((flags & 0xFA) != 0) // 只有 bit 0 與 bit 2 在 v1 有定義
            throw new FormatException($"reserved flag bits are set: {flags:X2}");

        short rawTemperatureTenths =
            BinaryPrimitives.ReadInt16BigEndian(body.Slice(5, 2));
        int nameLength = body[7];
        if (nameLength > 32)
            throw new FormatException($"name length exceeds 32 bytes: {nameLength}");
        if (body.Length != 8 + nameLength)
            throw new FormatException("body length does not match nameLength");

        string name;
        try
        {
            name = StrictUtf8.GetString(body.Slice(8, nameLength));
        }
        catch (DecoderFallbackException ex)
        {
            throw new FormatException("name is not valid UTF-8", ex);
        }

        bool valueValid = (flags & 0x01) != 0;
        bool alarm = (flags & 0x04) != 0;
        decimal? temperatureC = valueValid
            ? rawTemperatureTenths / 10m
            : null;
        return new StatusReply(
            requestId, valueValid, alarm, rawTemperatureTenths, temperatureC, name);
    }
}
